import { CalendarComponent, CalendarMode, Step } from 'ionic2-calendar/calendar';
import { Component, ViewChild, OnInit, Inject, LOCALE_ID } from '@angular/core';
import { AlertController, ModalController } from '@ionic/angular';
import { formatDate } from '@angular/common';
import { UserService } from 'src/app/services/emis/user.service';
import { ActivatedRoute, Router } from '@angular/router';
import { UserSessionService } from 'src/app/services/usersession.service';
import { AutoSlotPage } from '../auto-slot/auto-slot.page';
import { AlertService } from 'src/app/services/alert.service';
@Component({
  selector: 'app-stem-calendar',
  templateUrl: './stem-calendar.page.html',
  styleUrls: ['./stem-calendar.page.scss'],
})
export class StemCalendarPage implements OnInit {

  eventSource = [];
  viewTitle: string;
  isToday: boolean;

  calendar = {
    mode: 'month' as CalendarMode,
    step: 30 as Step,
    currentDate: new Date(),
    dateFormatter: {
      formatMonthViewDay: function (date: Date) {
        return date.getDate().toString();
      },
      formatMonthViewDayHeader: function (date: Date) {
        return 'MonMH';
      },
      formatMonthViewTitle: function (date: Date) {
        return 'testMT';
      },
      formatWeekViewDayHeader: function (date: Date) {
        return 'MonWH';
      },
      formatWeekViewTitle: function (date: Date) {
        return 'testWT';
      },
      formatWeekViewHourColumn: function (date: Date) {
        return 'testWH';
      },
      formatDayViewHourColumn: function (date: Date) {
        return 'testDH';
      },
      formatDayViewTitle: function (date: Date) {
        return 'testDT';
      }
    }
  };

  holidayData: any;

  schoolId: any;
  routeData: any;
  slotFinal: any;
  school_name: any;
  item: any;
  slot: any;

  slot1: boolean;
  slot2: boolean;
  eventOn: boolean;
  filter: any[] = [];
  colorOnchange: boolean;
  colorOnchange1: boolean;
  holiday: boolean;
  arrayFinal: any[] = [];
  username: any;
  finalDate: Date;
  notes: boolean;

  date = new Date();
  notes1: boolean;
  tomorrow: Date;
  schoolAvaData: any[] = [];
  final: any[] = [];
  arrayfinalFilter: any[];
  startdate: any;
  enddate: any;
  statusMode: any;
  cycle: any;
  eventstartdate: any;
  eventenddate: any;

  constructor(
    private alertCtrl: AlertController,
    private modalCtrl: ModalController,
    private userService: UserService,
    private route: ActivatedRoute,
    private router: Router,
    private usersessionService: UserSessionService,
    private alertService: AlertService,
  ) {
    this.username = this.usersessionService.emis_username();
  }

  ngOnInit() {
  }

  ionViewDidEnter() {
    this.routeData = this.route.snapshot;
    this.schoolId = this.routeData.queryParams.schoolId;
    this.slot = this.routeData.queryParams.slot;
    this.slotFinal = this.routeData.queryParams.slot;
    this.school_name = this.routeData.queryParams.school_name;
    this.item = this.routeData.queryParams.item;
    this.startdate = this.routeData.queryParams.startdate;
    this.enddate = this.routeData.queryParams.enddate;
    this.statusMode = this.routeData.queryParams.statusMode;
    this.cycle = this.routeData.queryParams.cycle;
    this.eventstartdate = this.routeData.queryParams.eventstartdate;
    this.eventenddate = this.routeData.queryParams.eventenddate;

    console.log(this.eventstartdate,"123",this.eventenddate);
    this.eventOn = false
    this.holiday = false
    this.clear()
    this.viewData()

    var tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    this.tomorrow = tomorrow

  }

  // Calendar event was clicked
  async onEventSelected(event) {

    // Use Angular date pipe for conversion
    let start = formatDate(9, 'medium', '');
    let end = formatDate(1, 'medium', '');

    const alert = await this.alertCtrl.create({
      header: event.title,
      subHeader: event.desc,
      message: 'From: ' + start + '<br><br>To: ' + end,
      buttons: ['OK'],
    });
    alert.present();
  }

  removeEvents() {
    this.eventSource = [];
  }

  viewData() {
    this.holidayData = []
    this.schoolAvaData = []
 
    this.userService.getautoAssignSlot(this.schoolId,this.username).subscribe((response) => {

    // this.userService.getschoolSlot(this.schoolId).subscribe((item2) => {

      // let response;
      // if(this.item == 'auto') {
      //   response = item1
      // } else {
      //   response = item2
      // }

      this.arrayfinalFilter = response.result

      let filter = response.result.filter(
        (item: any) => item.planning_date != null || item.holiday == 1 || item.session2 != null || item.session1 != null
      );
      this.holidayData.push(filter)

      let filter1 = response.result.filter(
        (item: any) => item.holiday == 0 && (item.session2 == null || item.session1 == null)
      );
      this.schoolAvaData.push(filter1)

      this.createEvents()
    })
  // })

  }

  navigateBack() {
    this.router.navigate(['/tabs/school-schedule'], { queryParams: { "item": this.item, "startdate": this.startdate, "enddate": this.enddate,"eventstartdate": this.eventstartdate, "eventenddate": this.eventenddate, 'statusMode': this.statusMode, 'cycle': this.cycle} });
    }

  onViewTitleChanged(title) {
    this.viewTitle = title;
  }

  createEvents() {

    var events = [];
    for (var i = 0; i < this.holidayData[0].length; i += 1) {

      let array = this.holidayData[0]

      var titles1;
      if (array[i].session1 == null) {
        titles1 = 'Session 1 - No Event'
      } else {
        let tit1;
        tit1 = array[i].Session1_program_type
        titles1 = 'Session 1 - ' + tit1
      }

      var titles2;
      if (array[i].session2 == null) {
        titles2 = 'Session 2 - No Event'
      } else {
        let tit2;
        tit2 = array[i].Session2_program_type
        titles2 = 'Session 2 - ' + tit2
      }

      var titles;
      if (array[i].holiday == 0 && array[i].session1 == null && array[i].session2 == null) {
        titles = 'No Event'
      } else {
        titles = titles1 + '  ,  ' + titles2
      }

      if (array[i].holiday == 1) {
        titles = 'Holiday'
      } else {
        titles = titles1 + '  ,  ' + titles2
      }

      var date = new Date(array[i].date);
      var startTime;
      var endTime;
      startTime = new Date(
        Date.UTC(
          date.getUTCFullYear(),
          date.getUTCMonth(),
          date.getUTCDate(),
          0,
          date.getHours(),
          date.getMinutes()
        )
      );

      endTime = new Date(
        Date.UTC(
          date.getUTCFullYear(),
          date.getUTCMonth(),
          date.getUTCDate(),
          0,
          date.getHours(),
          date.getMinutes()

        )
      );
      events.push({
        title: titles,
        startTime: startTime,
        endTime: endTime,
        allDay: false,
        color: '#46c4f3'
      });
    }
    this.eventSource = events;
  }

  onCurrentDateChanged(event: Date) {
    var today = new Date(this.eventstartdate);
    if (event < new Date(this.eventstartdate)) {
      this.notes = true
    } else {
      // if (event < new Date(new Date().setDate(today.getDate() + 40))) {
        debugger
        console.log(new Date(event) ,new Date(this.eventenddate))

        var mm
        var dd
        const eventend = new Date(this.eventenddate);
        const yyyy = eventend.getFullYear();
        mm = eventend.getMonth() + 1; // Months start at 0! 
        dd = eventend.getDate() + 1;
        if (dd < 10) { dd = '0' + dd; }
        if (mm < 10) { mm = '0' + mm; }
        const formattedToday = yyyy + '-' + mm + '-' + dd;

        // var mm1
        // var dd1
        // const eventend1 = new Date(event);
        // const yyyy1 = eventend.getFullYear();
        // mm1 = eventend.getMonth() + 1; // Months start at 0! 
        // dd1 = eventend.getDate() + 1;
        // if (dd1 < 10) { dd1 = '0' + dd1; }
        // if (mm1 < 10) { mm1 = '0' + mm1; }
        // const formattedToday1 = yyyy + '-' + mm1 + '-' + dd1;
        
      if (new Date(event) <= new Date(formattedToday)) {
        this.notes = false
        this.notes1 = false
      } else {
        this.notes = false
        this.notes1 = true
      }
    }

    this.slot1 = false;
    this.slot2 = false;
    this.filter = []
    this.eventOn = true
    this.holiday = true
    this.colorOnchange = false
    this.colorOnchange1 = false
    this.finalDate = event

    var date = new Date(event),
      mnth = ("0" + (date.getMonth() + 1)).slice(-2),
      day = ("0" + date.getDate()).slice(-2);

    let filter
    filter = this.holidayData[0].filter(
      (item: any) => item.date == date.getFullYear() + '-' + mnth + '-' + day
    );
    this.filter.push(filter[0])

    if (this.filter.length != 0) {

      if (this.filter[0].holiday == 1) {
        this.holiday = false;
      } else {
        this.holiday = true;
      }

      if (this.filter[0].session1 == null) {
        this.slot1 = false;
      } else {
        this.slot1 = true;
      }

      if (this.filter[0].session2 == null) {
        this.slot2 = false;
      } else {
        this.slot2 = true;
      }

      if (this.filter[0].session1 == null && this.filter[0].session2 == null) {
        this.slot1 = false;
        this.slot2 = false;
      } else {
      }

    } else {
      // this.slot1 = false;
      // this.slot2 = false; 
    }

  }

  slot1On() {
    let data = {
      "date": this.finalDate,
      "holiday": '0',
      "program_type": '3',
      "user_id": this.username,
      "planning_date": this.finalDate,
      "session": '1',
    }

    this.arrayFinal.push(data)
    this.colorOnchange = true
  }

  slot2On() {
    let data = {
      "date": this.finalDate,
      "holiday": '0',
      "program_type": '3',
      "user_id": this.username,
      "planning_date": this.finalDate,
      "session": '2'
    }
    this.arrayFinal.push(data)
    this.colorOnchange1 = true
  }

  onSave() {
    for (let i = 0; i < this.arrayFinal.length; i++) {
      let data1 = {
        "IndexId": "",
        "ProgramType": "3",
        "UserId": this.username,
        "SchoolId": this.schoolId,
        "PlanningDate": this.arrayFinal[i].date,
        "Session": this.arrayFinal[i].session,

      }
      let data = {
        "records": data1
      }
      this.userService.slotData(data).subscribe((response) => {
        this.router.navigate(['/tabs/school-schedule'], { queryParams: { "item": this.item, "startdate": this.startdate, "enddate": this.enddate,"eventstartdate": this.eventstartdate, "eventenddate": this.eventenddate, 'statusMode': this.statusMode, 'cycle': this.cycle} });
      })
    }
  }

  clear() {
    this.arrayFinal = []
  }

  autoslot() {
    this.final = []
    this.arrayFinal = []

    this.slot = this.slotFinal

    if (this.slot == 1) {
      var date = new Date(this.finalDate),
        mnth = ("0" + (date.getMonth() + 1)).slice(-2),
        day = ("0" + date.getDate()).slice(-2);
      this.arrayFinal = []

      let filter1 = this.schoolAvaData[0].filter(
        (item: any) => item.date == date.getFullYear() + '-' + mnth + '-' + day && item.session1 == null);

      let data = {
        "date": this.finalDate,
        "holiday": '0',
        "program_type": '3',
        "user_id": this.username,
        "planning_date": date.getFullYear() + '-' + mnth + '-' + day,
        "session": '1'
      }
      this.arrayFinal.push(data)

      if (filter1.length == 0) {
        this.arrayFinal = []
        let filter2 = this.schoolAvaData[0].filter(
          (item: any) => item.date == date.getFullYear() + '-' + mnth + '-' + day && item.session2 == null);
        console.log(filter2, "filter2")
        let data = {
          "date": this.finalDate,
          "holiday": '0',
          "program_type": '3',
          "user_id": this.username,
          "planning_date": date.getFullYear() + '-' + mnth + '-' + day,
          "session": '2'
        }
        this.arrayFinal.push(data)
      }
    } else {

      for (let i = 0; i < this.slot; i++) {

        var date1 = new Date(
          Date.UTC(
            this.finalDate.getUTCFullYear(),
            this.finalDate.getUTCMonth(),
            this.finalDate.getUTCDate() + i,
            0,
            this.finalDate.getHours(),
            this.finalDate.getMinutes()
          ))

        var date = new Date(date1),
        mnth = ("0" + (date.getMonth() + 1)).slice(-2),
        day = ("0" + date.getDate()).slice(-2);

          if(parseInt(day) == 32){
            mnth = ("0" + (date.getMonth() + 2)).slice(-2),
            date.setDate(date.getDate() + 1);
          }

          if(parseInt(day) == 33){
            mnth = ("0" + (date.getMonth() + 2)).slice(-2), 
            date.setDate(date.getDate() + 2);
          }

          if(parseInt(day) == 34){
            mnth = ("0" + (date.getMonth() + 2)).slice(-2), 
            date.setDate(date.getDate() + 3);
          }

          if(parseInt(day) == 35){
            mnth = ("0" + (date.getMonth() + 2)).slice(-2), 
            date.setDate(date.getDate() + 4);
          }

          // 

        let filter1 = this.schoolAvaData[0].filter(
          (item: any) => item.date == date.getFullYear() + '-' + mnth + '-' + day && item.session1 == null && item.holiday == 0);

        let filter2 = this.schoolAvaData[0].filter(
          (item: any) => item.date == date.getFullYear() + '-' + mnth + '-' + day && item.session2 == null && item.holiday == 0);

        let filter3 = this.arrayfinalFilter.filter(
          (item: any) => item.date == date.getFullYear() + '-' + mnth + '-' + day && ((item.session1 != null && item.session2 != null && item.holiday == 0) || ((item.session1 != null || item.session2 != null) && item.holiday == 0) || (item.holiday == 1)));

        if (filter1.length == 0 && filter2.length == 0) {
          this.slot = parseInt(this.slot) + 1
        } else {

          if (filter1.length == 0 && filter3.length != 0) {
            this.slot = parseInt(this.slot) + 0.5
          } else {
            if (this.final.length < parseInt(this.slotFinal)) {
              let data = {
                "date": date,
                "holiday": '0',
                "program_type": '3',
                "user_id": this.username,
                "planning_date": date.getFullYear() + '-' + mnth + '-' + day,
                "session": '1'
              }
              this.arrayFinal.push(data)
              this.final.push(filter1)
            }
          }

          if (filter2.length == 0 && filter3.length != 0) {
            this.slot = parseInt(this.slot) + 0.5
          } else {
            if (this.final.length < parseInt(this.slotFinal)) {
              let data = {
                "date": date,
                "holiday": '0',
                "program_type": '3',
                "user_id": this.username,
                "planning_date": date.getFullYear() + '-' + mnth + '-' + day,
                "session": '2'
              }
              this.arrayFinal.push(data)
              this.final.push(filter2)
            }
          }
 
        }

      }
    }

    this.slotview()
  }

  async slotview() {

    if(this.slot2 && !this.colorOnchange1 && this.slot1 && !this.colorOnchange)
    {
      this.alertService.alert("Already booked Slot")
    } else { 
    if(this.eventOn && this.holiday && !this.notes && !this.notes1) {
    const modal = await this.modalCtrl.create({
      component: AutoSlotPage,
      componentProps: { schoolClassData: this.arrayFinal , school_name: this.school_name, slot: this.slotFinal, school_id: this.schoolId,item: this.item, "startdate": this.startdate, "enddate": this.enddate,"eventstartdate": this.eventstartdate, "eventenddate": this.eventenddate, 'statusMode': this.statusMode, 'cycle': this.cycle},
      cssClass: 'view-image-modal'
    });
    await modal.present();
  } else {
    this.alertService.alert("Couldn't book Slot")
  }
  }
     
}

}